// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetHealth Service and database health
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetIcalExport The property's calendar for OTAs to import
	// (GET /ical/{file})
	GetIcalExport(w http.ResponseWriter, r *http.Request, file string, params GetIcalExportParams)
	// RenameAccount Rename the account in X-Account-Id
	// (PATCH /v1/account)
	RenameAccount(w http.ResponseWriter, r *http.Request)
	// ExportAccount Everything in the account, as one document
	// (GET /v1/account/export)
	ExportAccount(w http.ResponseWriter, r *http.Request)
	// ListAccounts Accounts the signed-in user belongs to
	// (GET /v1/accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request)
	// CreateAccount Create an account with the signed-in user as its owner
	// (POST /v1/accounts)
	CreateAccount(w http.ResponseWriter, r *http.Request)
	// ListActivity What happened in the account, newest first
	// (GET /v1/activity)
	ListActivity(w http.ResponseWriter, r *http.Request, params ListActivityParams)
	// MarkActivityRead Mark everything up to now as read for the caller
	// (POST /v1/activity/read)
	MarkActivityRead(w http.ResponseWriter, r *http.Request)
	// Logout End the session behind a refresh token
	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// RequestOtp Text a 6-digit sign-in code to a phone number
	// (POST /v1/auth/otp)
	RequestOtp(w http.ResponseWriter, r *http.Request)
	// RefreshSession Exchange a refresh token for new tokens
	// (POST /v1/auth/refresh)
	RefreshSession(w http.ResponseWriter, r *http.Request)
	// VerifyOtp Check a code and sign in, creating the user on first sign-in
	// (POST /v1/auth/verify)
	VerifyOtp(w http.ResponseWriter, r *http.Request)
	// CreateBlock Close nights on some units
	// (POST /v1/blocks)
	CreateBlock(w http.ResponseWriter, r *http.Request)
	// DeleteBlock Open a block's nights again
	// (DELETE /v1/blocks/{blockId})
	DeleteBlock(w http.ResponseWriter, r *http.Request, blockId BlockId)
	// ListBookings Stays the caller can see, by arrival
	// (GET /v1/bookings)
	ListBookings(w http.ResponseWriter, r *http.Request, params ListBookingsParams)
	// CreateBooking Add a stay the owner took directly
	// (POST /v1/bookings)
	CreateBooking(w http.ResponseWriter, r *http.Request, params CreateBookingParams)
	// GetBooking One stay with its price lines, payments and slips
	// (GET /v1/bookings/{bookingId})
	GetBooking(w http.ResponseWriter, r *http.Request, bookingId BookingId)
	// UpdateBooking Change a stay
	// (PATCH /v1/bookings/{bookingId})
	UpdateBooking(w http.ResponseWriter, r *http.Request, bookingId BookingId)
	// CancelBooking Cancel a stay and record any refund
	// (POST /v1/bookings/{bookingId}/cancel)
	CancelBooking(w http.ResponseWriter, r *http.Request, bookingId BookingId, params CancelBookingParams)
	// EraseBookingGuest Erase the details of the guest behind a stay
	// (POST /v1/bookings/{bookingId}/erase-guest)
	EraseBookingGuest(w http.ResponseWriter, r *http.Request, bookingId BookingId)
	// RecordPayment Record money the guest paid
	// (POST /v1/bookings/{bookingId}/payments)
	RecordPayment(w http.ResponseWriter, r *http.Request, bookingId BookingId, params RecordPaymentParams)
	// TransitionBooking Move a stay to its next status
	// (POST /v1/bookings/{bookingId}/transitions)
	TransitionBooking(w http.ResponseWriter, r *http.Request, bookingId BookingId)
	// SyncIcalFeed Read an imported calendar again now
	// (POST /v1/ical-feeds/{feedId}/sync)
	SyncIcalFeed(w http.ResponseWriter, r *http.Request, feedId FeedId)
	// AcceptInvite Join the account an invite is for
	// (POST /v1/invites/accept)
	AcceptInvite(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user and the accounts they belong to
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Update the signed-in user's profile
	// (PATCH /v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// DeleteMe Delete the signed-in person and the accounts they own
	// (POST /v1/me/deletion)
	DeleteMe(w http.ResponseWriter, r *http.Request)
	// CreateMePhotoUpload Get a link to upload the signed-in person's profile photo
	// (POST /v1/me/photo)
	CreateMePhotoUpload(w http.ResponseWriter, r *http.Request)
	// GetNotificationPrefs How the caller wants to hear about each event in this account
	// (GET /v1/notification-prefs)
	GetNotificationPrefs(w http.ResponseWriter, r *http.Request)
	// SetNotificationPrefs Replace the caller's preferences for the events sent
	// (PUT /v1/notification-prefs)
	SetNotificationPrefs(w http.ResponseWriter, r *http.Request)
	// ListProperties List the properties the caller can see
	// (GET /v1/properties)
	ListProperties(w http.ResponseWriter, r *http.Request)
	// CreateProperty Create a property and its booking page address
	// (POST /v1/properties)
	CreateProperty(w http.ResponseWriter, r *http.Request)
	// GetProperty A property with its full setup
	// (GET /v1/properties/{id})
	GetProperty(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// UpdateProperty Change some of a property's setup
	// (PATCH /v1/properties/{id})
	UpdateProperty(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// GetCalendar Blocks and rate overrides for a stretch of nights
	// (GET /v1/properties/{id}/calendar)
	GetCalendar(w http.ResponseWriter, r *http.Request, id Id, params GetCalendarParams)
	// GetGuestBooking A guest's own booking
	// (GET /v1/public/bookings/{bookingId})
	GetGuestBooking(w http.ResponseWriter, r *http.Request, bookingId BookingId, params GetGuestBookingParams)
	// AddGuestSlip Send an uploaded bank slip to the owner
	// (POST /v1/public/bookings/{bookingId}/slips)
	AddGuestSlip(w http.ResponseWriter, r *http.Request, bookingId BookingId, params AddGuestSlipParams)
	// CreateGuestUpload Get a link to upload a bank slip
	// (POST /v1/public/bookings/{bookingId}/uploads)
	CreateGuestUpload(w http.ResponseWriter, r *http.Request, bookingId BookingId, params CreateGuestUploadParams)
	// PreviewInvite What an invite link is for, before the person signs in
	// (POST /v1/public/invites/preview)
	PreviewInvite(w http.ResponseWriter, r *http.Request)
	// ListPlans Plans and their web prices
	// (GET /v1/public/plans)
	ListPlans(w http.ResponseWriter, r *http.Request)
	// GetPublicProperty Public details for a property's booking page
	// (GET /v1/public/properties/{slug})
	GetPublicProperty(w http.ResponseWriter, r *http.Request, slug Slug)
	// GetPublicAvailability Nights each unit can't be booked, and days guests can't arrive
	// (GET /v1/public/properties/{slug}/availability)
	GetPublicAvailability(w http.ResponseWriter, r *http.Request, slug PropertySlug, params GetPublicAvailabilityParams)
	// CreateGuestBooking Book a stay from the booking page or widget
	// (POST /v1/public/properties/{slug}/bookings)
	CreateGuestBooking(w http.ResponseWriter, r *http.Request, slug PropertySlug, params CreateGuestBookingParams)
	// CreateHold Hold nights while the guest fills in the checkout
	// (POST /v1/public/properties/{slug}/holds)
	CreateHold(w http.ResponseWriter, r *http.Request, slug PropertySlug)
	// CreatePublicQuote Price a stay a guest is choosing
	// (POST /v1/public/properties/{slug}/quote)
	CreatePublicQuote(w http.ResponseWriter, r *http.Request, slug PropertySlug)
	// RegisterPushToken Register this device's Expo push token for the signed-in session
	// (POST /v1/push-tokens)
	RegisterPushToken(w http.ResponseWriter, r *http.Request)
	// CreateQuote Price a stay
	// (POST /v1/quote)
	CreateQuote(w http.ResponseWriter, r *http.Request)
	// SetRateOverrides Set or clear the price and stay rules for some nights
	// (PUT /v1/rate-overrides)
	SetRateOverrides(w http.ResponseWriter, r *http.Request)
	// RejectSlip Turn down a bank slip the guest uploaded
	// (POST /v1/slips/{slipId}/reject)
	RejectSlip(w http.ResponseWriter, r *http.Request, slipId SlipId)
	// GetSubscription The account's plan, free period and bookable units
	// (GET /v1/subscription)
	GetSubscription(w http.ResponseWriter, r *http.Request)
	// CreateCheckout Start a web payment for one prepaid period
	// (POST /v1/subscription/checkout)
	CreateCheckout(w http.ResponseWriter, r *http.Request)
	// RefreshSubscription Read the account's store plans from RevenueCat now
	// (POST /v1/subscription/refresh)
	RefreshSubscription(w http.ResponseWriter, r *http.Request)
	// GetTeam The account's members and open invites
	// (GET /v1/team)
	GetTeam(w http.ResponseWriter, r *http.Request)
	// CreateInvite Invite someone by phone as a manager or caretaker
	// (POST /v1/team/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request)
	// RevokeInvite Revoke an open invite so its link stops working
	// (DELETE /v1/team/invites/{inviteId})
	RevokeInvite(w http.ResponseWriter, r *http.Request, inviteId InviteId)
	// RemoveMember Remove a member from the account
	// (DELETE /v1/team/members/{membershipId})
	RemoveMember(w http.ResponseWriter, r *http.Request, membershipId MembershipId)
	// UpdateMember Change a member's role or the properties they can see
	// (PATCH /v1/team/members/{membershipId})
	UpdateMember(w http.ResponseWriter, r *http.Request, membershipId MembershipId)
	// ListTemplates The account's message templates
	// (GET /v1/templates)
	ListTemplates(w http.ResponseWriter, r *http.Request)
	// UpdateTemplate Change a template's text
	// (PATCH /v1/templates/{templateId})
	UpdateTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)
	// CreateUpload Get a link to upload a photo or logo
	// (POST /v1/uploads)
	CreateUpload(w http.ResponseWriter, r *http.Request)
	// PaymentsLkWebhook Payment events from Payments.lk
	// (POST /webhooks/payments-lk)
	PaymentsLkWebhook(w http.ResponseWriter, r *http.Request, params PaymentsLkWebhookParams)
	// RevenueCatWebhook Subscription events from RevenueCat
	// (POST /webhooks/revenuecat)
	RevenueCatWebhook(w http.ResponseWriter, r *http.Request, params RevenueCatWebhookParams)
}

